mapper.select:

WHERE i.kind = #{kind}

    AND (i.invoice_no LIKE CONCAT('%', #{keyword}, '%') OR c.name LIKE CONCAT('%', #{keyword}, '%')
         OR s.name LIKE CONCAT('%', #{keyword}, '%'))

AND i.partner_id = #{partnerId}
AND i.status = #{status}
AND i.status = 'VALID' AND i.matched_amount <> i.amount
ORDER BY i.invoice_date DESC, i.id DESC
